<script setup>
import { onMounted, reactive, ref } from 'vue'; import { ElMessage,ElMessageBox } from 'element-plus'; import { api } from '../../lib/api.js'; import { hasPermission } from '../../lib/auth.js'; const rows=ref([]),dialog=ref(false),editing=ref(null); const form=reactive({brandCode:'',brandName:'',remark:'',status:true}); async function load(){try{rows.value=await api.brands()}catch(e){ElMessage.error(e.message)}} function open(x=null){editing.value=x?.id||null;Object.assign(form,x?{brandCode:x.brandCode,brandName:x.brandName,remark:x.remark,status:x.status}:{brandCode:'',brandName:'',remark:'',status:true});dialog.value=true} async function save(){try{editing.value?await api.updateBrand(editing.value,form):await api.createBrand(form);dialog.value=false;await load()}catch(e){ElMessage.error(e.message)}} async function toggle(x){try{await ElMessageBox.confirm('确认切换状态吗？');await api.brandStatus(x.id,!x.status);await load()}catch(e){if(e!=='cancel')ElMessage.error(e.message)}} onMounted(load)
</script><template><div class="page-heading"><h1>品牌管理</h1><el-button v-if="hasPermission('system.brand.create')" type="primary" @click="open()">新增品牌</el-button></div><el-card><el-table :data="rows"><el-table-column prop="brandCode" label="编号"/><el-table-column prop="brandName" label="名称"/><el-table-column prop="remark" label="备注"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="hasPermission('system.brand.update')" link @click="open(row)">编辑</el-button><el-button v-if="hasPermission('system.brand.disable')" link @click="toggle(row)">{{row.status?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" :title="editing?'编辑品牌':'新增品牌'"><el-form label-width="80px"><el-form-item label="编号"><el-input v-model="form.brandCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.brandName"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
